package cn.zhuatech.searchai.controller; import cn.zhuatech.searchai.common.ApiResponse; import cn.zhuatech.searchai.service.EnterpriseSearchService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/ai") @PreAuthorize("hasAnyRole('DOMAIN_USER','DOMAIN_OPERATOR','ADMIN')") public class AiFeatureController { private final EnterpriseSearchService service; public AiFeatureController(EnterpriseSearchService service){this.service=service;} @PostMapping("/search/plan") public ApiResponse<EnterpriseSearchService.Result> execute(@Valid @RequestBody EnterpriseSearchService.Request request){return ApiResponse.ok("权限感知搜索计划完成",service.plan(request));} }